//productModal logic
const modal_overlay = document.getElementById('modal_overlay');
const modalProductTitle = document.querySelector('.modal-product-title');
const modalVideo = document.getElementById('modalVideoIframe');
const modalGithubTitle = document.querySelector('.modal-github-title');
const modalDescription = document.querySelector('.modal-description');
const modalSvgContainer = document.querySelector('.modal-svg-container');
const modalCloseButton = document.getElementById('modal_close_button');
const modalContainer = document.querySelector('.modal-container');
const modalUsedTechTitle = document.querySelector('.Used-technologies-title');
const modalDeployTitle = document.querySelector('.modal-deploy-title');

var isOpen = false;

function openModal(product){
    if(isOpen === true){
        return
    }
    isOpen = true;
    product -= 1;
    document.body.style.overflow = "hidden"
    modal_overlay.style.visibility = "visible";
    modalContainer.style.opacity = "1";
    modalVideo.style.opacity = '1';
    modalInfo(product);
}

function modalInfo(product){
    if(currentLang === 'en'){
        modalProductTitle.textContent = `${products[product].title}`;
        modalVideo.src = getYouTubeEmbedUrl(products[product].youtube);
        modalGithubTitle.textContent = `Github: ${products[product].github}`;
        modalGithubTitle.href = products[product].github;
        products[product].deploy ? modalDeployTitle.textContent = `Deploy: ${products[product].deploy}` :  modalDeployTitle.textContent = '';
        products[product].deploy ? modalDeployTitle.href = products[product].deploy :  modalDeployTitle.href = '';
        modalDescription.textContent = `Description: ${products[product].description}`;
        modalUsedTechTitle.textContent = 'Used technologies:';
        products[product].technologies.forEach(svgString=>{
            const li = document.createElement('li');
            li.innerHTML = svgString; 
            modalSvgContainer.append(li);
        });
    }
    else{
        modalProductTitle.textContent = `${productsV2[product].title}`;
        modalVideo.src = getYouTubeEmbedUrl(productsV2[product].youtube);
        modalGithubTitle.textContent = `Гитхаб: ${productsV2[product].github}`;
        products[product].deploy ? modalDeployTitle.textContent = `Вы можете протестировать: ${products[product].deploy}` :  modalDeployTitle.textContent = '';
        products[product].deploy ? modalDeployTitle.href = products[product].deploy :  modalDeployTitle.href = '';
        modalGithubTitle.href = productsV2[product].github;
        modalDescription.textContent = `Описание: ${productsV2[product].description}`;
        modalUsedTechTitle.textContent = 'Используемые технологии:';
        productsV2[product].technologies.forEach(svgString=>{
            const li = document.createElement('li');
            li.innerHTML = svgString; 
            modalSvgContainer.append(li);
        });
    }
    
}

function modalClearInfo(){
    modalProductTitle.textContent = '';
    modalGithubTitle.textContent = '';
    modalGithubTitle.href = '#';
    modalDescription.textContent = '';
    modalVideo.src = '';
    modalVideo.style.opacity = '0';
    modalSvgContainer.innerHTML = '';
    modalUsedTechTitle.textContent = '';
    modalDeployTitle.textContent = '';
    modalDeployTitle.href = '#';
}

function getYouTubeEmbedUrl(youtubeUrl) {
    const videoIdMatch = youtubeUrl.match(/v=([^&]+)/);
    if (videoIdMatch && videoIdMatch[1]) {
        return `https://www.youtube.com/embed/${videoIdMatch[1]}`;
    }
    return '';
}

modalCloseButton.addEventListener('click',()=>{
    modalClearInfo();
    document.body.style.overflow = "visible"
    modalContainer.style.opacity = "0";
    modal_overlay.style.visibility = "hidden";
    isOpen = false;
});

modal_overlay.addEventListener('click', (event) => {
    // event.target - элемент, на котором произошёл клик
    // event.currentTarget - элемент, к которому прикреплён обработчик (в данном случае modal_overlay)
    // Если клик был непосредственно на modal_overlay (а не на его потомке),
    // то target и currentTarget будут совпадать.
    if (event.target === event.currentTarget) {
        modalClearInfo();
        document.body.style.overflow = "visible"
        modalContainer.style.opacity = "0";
        modal_overlay.style.visibility = "hidden";
        isOpen = false;
    }
});


